[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en" data-theme="dark">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CommerceForge Dev Docs — Build for the Commerce Platform</title>
<style>
/* =============================================
   CSS Custom Properties
   ============================================= */
:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #21262d;
  --bg-elevated: #1c2129;
  --border-default: #30363d;
  --border-muted: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-tertiary: #6e7681;
  --accent: #00e5ff;
  --accent-green: #3bf4c0;
  --accent-purple: #bc8cff;
  --accent-blue: #79c0ff;
  --accent-orange: #ffa657;
  --code-bg: #0d1117;
  --code-border: #30363d;
  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', 'SF Mono', monospace;
  --radius-sm: 6px;
  --radius: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1200px;
  --nav-height: 64px;
}

[data-theme="light"] {
  --bg-primary: #ffffff;
  --bg-secondary: #f6f8fa;
  --bg-tertiary: #eaeef2;
  --bg-elevated: #f0f2f5;
  --border-default: #d0d7de;
  --border-muted: #e8ecf0;
  --text-primary: #1f2328;
  --text-secondary: #656d76;
  --text-tertiary: #8b949e;
  --code-bg: #f6f8fa;
  --code-border: #d0d7de;
}

/* =============================================
   Reset & Base
   ============================================= */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-green); }

img, svg { display: block; max-width: 100%; }

button { cursor: pointer; font-family: inherit; }

/* =============================================
   Navigation
   ============================================= */
.nav {
  position: sticky; top: 0; z-index: 100;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-default);
  height: var(--nav-height);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-brand {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-brand-icon {
  width: 28px; height: 28px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
  font-weight: 800;
  color: #0d1117;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-btn {
  background: none;
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: all var(--transition);
  min-height: 36px;
}
.nav-btn:hover { color: var(--text-primary); border-color: var(--text-tertiary); }
.nav-btn svg { width: 16px; height: 16px; }

.nav-btn-primary {
  background: var(--accent-green);
  color: #0d1117;
  border-color: var(--accent-green);
  font-weight: 600;
  padding: 6px 16px;
}
.nav-btn-primary:hover {
  background: #2de4b0;
  border-color: #2de4b0;
  color: #0d1117;
}

.nav-search {
  position: relative;
}
.nav-search-input {
  position: absolute;
  right: 0; top: 100%;
  margin-top: 8px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius);
  padding: 10px 16px;
  font-size: 0.875rem;
  color: var(--text-primary);
  font-family: var(--font-sans);
  width: 280px;
  display: none;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}
.nav-search-input.visible { display: block; }
.nav-search-input::placeholder { color: var(--text-tertiary); }

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 1.5rem;
  padding: 4px;
  min-width: 44px;
  min-height: 44px;
}

@media (max-width: 768px) {
  .mobile-menu-btn { display: flex; align-items: center; justify-content: center; }
  .nav-links {
    display: none;
    position: absolute;
    top: var(--nav-height);
    left: 0; right: 0;
    background: var(--bg-primary);
    border-bottom: 1px solid var(--border-default);
    flex-direction: column;
    padding: 16px 24px;
    gap: 4px;
  }
  .nav-links.mobile-open { display: flex; }
  .nav-links a { width: 100%; padding: 12px; font-size: 1rem; }
  .nav-actions { gap: 4px; }
  .nav-actions .nav-btn span { display: none; }
}

/* =============================================
   Hero Section
   ============================================= */
.hero {
  padding: 80px 24px 64px;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(0, 229, 255, 0.08);
  border: 1px solid rgba(0, 229, 255, 0.2);
  color: var(--accent);
  font-size: 0.8rem;
  font-weight: 500;
  padding: 4px 12px;
  border-radius: 100px;
  margin-bottom: 24px;
}
.hero-badge-dot {
  width: 6px; height: 6px;
  background: var(--accent-green);
  border-radius: 50%;
  animation: pulse 2s ease infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, #8b949e 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
[data-theme="light"] .hero h1 {
  background: linear-gradient(135deg, #1f2328 0%, #656d76 100%);
  -webkit-background-clip: text;
  background-clip: text;
}

.hero p {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto 40px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

/* =============================================
   Buttons
   ============================================= */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 12px 24px;
  border-radius: var(--radius);
  font-size: 0.9rem;
  font-weight: 600;
  transition: all var(--transition);
  border: 1px solid transparent;
  white-space: nowrap;
  min-height: 44px;
}

.btn-primary {
  background: var(--accent-green);
  color: #0d1117;
  border-color: var(--accent-green);
}
.btn-primary:hover {
  background: #2de4b0;
  color: #0d1117;
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(59, 244, 192, 0.2);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border-color: var(--border-default);
}
.btn-secondary:hover {
  border-color: var(--text-tertiary);
  background: var(--bg-tertiary);
  transform: translateY(-1px);
}

.btn-accent {
  background: var(--accent);
  color: #0d1117;
  border-color: var(--accent);
}
.btn-accent:hover {
  background: #33eaff;
  color: #0d1117;
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(0, 229, 255, 0.2);
}

/* =============================================
   Section Common
   ============================================= */
.section {
  padding: 80px 24px;
}

.section-header {
  text-align: center;
  margin-bottom: 48px;
}

.section-header h2 {
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section-header p {
  color: var(--text-secondary);
  font-size: 1rem;
  max-width: 560px;
  margin: 0 auto;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
}

/* =============================================
   Product Cards (Home)
   ============================================= */
.products-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  padding: 0 24px;
  max-width: var(--max-width);
  margin: 0 auto 80px;
}

.product-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  position: relative;
  overflow: hidden;
  transition: all var(--transition-slow);
}
.product-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
}
.product-card:nth-child(1)::before { background: var(--accent); }
.product-card:nth-child(2)::before { background: var(--accent-purple); }
.product-card:nth-child(3)::before { background: var(--accent-green); }

.product-card:hover {
  border-color: var(--text-tertiary);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}

.product-card-icon {
  width: 44px; height: 44px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  margin-bottom: 20px;
}
.product-card:nth-child(1) .product-card-icon { background: rgba(0, 229, 255, 0.12); }
.product-card:nth-child(2) .product-card-icon { background: rgba(188, 140, 255, 0.12); }
.product-card:nth-child(3) .product-card-icon { background: rgba(59, 244, 192, 0.12); }

.product-card h3 {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.product-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 24px;
}

.product-card .btn {
  margin-top: auto;
}

@media (max-width: 900px) {
  .products-grid {
    grid-template-columns: 1fr;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
  }
}

/* =============================================
   CLI Setup Section
   ============================================= */
.cli-section {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-default);
  border-bottom: 1px solid var(--border-default);
}

.cli-section .container {
  max-width: 900px;
}

/* Accordion */
.accordion { display: flex; flex-direction: column; gap: 8px; }

.accordion-item {
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-primary);
  transition: border-color var(--transition);
}
.accordion-item.active { border-color: var(--accent); }

.accordion-header {
  width: 100%;
  background: none;
  border: none;
  color: var(--text-primary);
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: space-between;
  text-align: left;
  min-height: 44px;
  transition: color var(--transition);
}
.accordion-header:hover { color: var(--accent); }

.accordion-icon {
  width: 24px; height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition-slow);
  color: var(--text-tertiary);
  flex-shrink: 0;
}
.accordion-item.active .accordion-icon { transform: rotate(180deg); color: var(--accent); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}
.accordion-item.active .accordion-body { max-height: 600px; }

.accordion-content {
  padding: 0 24px 24px;
}

/* Steps */
.steps { list-style: none; counter-reset: step; margin-bottom: 24px; }
.steps li {
  counter-increment: step;
  padding: 8px 0 8px 32px;
  position: relative;
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}
.steps li::before {
  content: counter(step);
  position: absolute;
  left: 0; top: 10px;
  width: 20px; height: 20px;
  background: var(--bg-tertiary);
  border-radius: 50%;
  font-size: 0.7rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border-default);
  margin-bottom: 0;
}

.tab-btn {
  background: none;
  border: none;
  color: var(--text-tertiary);
  padding: 10px 16px;
  font-size: 0.8rem;
  font-weight: 600;
  font-family: var(--font-mono);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: all var(--transition);
  min-height: 40px;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.tab-content { display: none; }
.tab-content.active { display: block; }

/* Code Block */
.code-block {
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  border-top: none;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  padding: 16px 20px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.code-block code {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--accent-green);
  line-height: 1.5;
  word-break: break-all;
}

.copy-btn {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.7rem;
  font-family: var(--font-sans);
  font-weight: 500;
  transition: all var(--transition);
  white-space: nowrap;
  flex-shrink: 0;
  margin-left: 12px;
  min-height: 32px;
}
.copy-btn:hover { color: var(--text-primary); border-color: var(--text-tertiary); }
.copy-btn.copied { color: var(--accent-green); border-color: var(--accent-green); }

.init-command {
  margin-top: 16px;
  padding: 12px 20px;
  background: var(--bg-tertiary);
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 0.8rem;
  color: var(--text-secondary);
}

.init-command strong {
  color: var(--accent);
  font-weight: 500;
}

/* =============================================
   Launch CTA Section
   ============================================= */
.launch-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 900px;
  margin: 0 auto;
}

.launch-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  transition: all var(--transition);
}

.launch-card:hover {
  border-color: var(--text-tertiary);
  transform: translateY(-2px);
}

.launch-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin-bottom: 20px;
  line-height: 1.5;
}

@media (max-width: 640px) {
  .launch-grid { grid-template-columns: 1fr; }
}

/* =============================================
   Community Section
   ============================================= */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.community-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.community-card:hover {
  border-color: var(--accent);
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(0, 229, 255, 0.08);
}

.community-card h4 {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-primary);
}

.community-card .arrow {
  color: var(--accent);
  font-weight: 600;
  font-size: 0.85rem;
}

@media (max-width: 900px) {
  .community-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 500px) {
  .community-grid { grid-template-columns: 1fr; }
}

/* =============================================
   Footer
   ============================================= */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-default);
  padding: 64px 24px 32px;
}

.footer-grid {
  max-width: var(--max-width);
  margin: 0 auto 48px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
}

.footer-col h4 {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  max-width: var(--max-width);
  margin: 0 auto;
  padding-top: 24px;
  border-top: 1px solid var(--border-default);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: var(--text-tertiary);
}

@media (max-width: 768px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }
}
@media (max-width: 500px) {
  .footer-grid { grid-template-columns: 1fr; }
}
</style>
</head>
