      <li><a href="agents.html">Agents</a></li>
      <li><a href="support.html">Help</a></li>
    </ul>

    <div class="nav-actions">
      <div class="nav-search">
        <button class="nav-btn" id="searchToggle" aria-label="Search documentation" title="Search">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
          <span>Search</span>
        </button>
        <input type="text" class="nav-search-input" id="searchInput" placeholder="Search documentation...">
      </div>
      <button class="nav-btn" id="themeToggle" aria-label="Toggle light/dark mode" title="Toggle theme">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" id="themeIcon"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>
      </button>
      <button class="nav-btn nav-btn-primary">Log in</button>
      <button class="mobile-menu-btn" id="mobileMenuBtn" aria-label="Open menu" aria-expanded="false">☰</button>
    </div>
  </div>
</nav>

<!-- Hero Section -->
<section class="hero" aria-labelledby="heroTitle">
  <div class="hero-badge">
    <span class="hero-badge-dot" aria-hidden="true"></span>
    CLI 3.0 now available
  </div>
  <h1 id="heroTitle">CommerceForge<br>Dev Docs</h1>
  <p>Learn how to build an app, or customize your storefront. Whether you're just getting started, deep in the development process, or ready to distribute and monetize your work, CommerceForge's docs, dev tools and frameworks make building easy and efficient.</p>
  <div class="hero-ctas">
