  const nav = document.getElementById('navLinks');
  btn.addEventListener('click', function() {
    const open = nav.classList.toggle('mobile-open');
    btn.setAttribute('aria-expanded', open);
    btn.textContent = open ? '✕' : '☰';
  });
})();

