// Search Toggle
// =============================================
(function() {
  const toggle = document.getElementById('searchToggle');
  const input = document.getElementById('searchInput');
  toggle.addEventListener('click', function(e) {
    e.stopPropagation();
    input.classList.toggle('visible');
    if (input.classList.contains('visible')) input.focus();
  });
  document.addEventListener('click', function(e) {
    if (!toggle.contains(e.target) && !input.contains(e.target)) {
      input.classList.remove('visible');
    }
  });
})();

// =============================================
// Theme Toggle (Dark/Light)
// =============================================
(function() {
  const btn = document.getElementById('themeToggle');
  const icon = document.getElementById('themeIcon');
  btn.addEventListener('click', function() {
    const html = document.documentElement;
    const current = html.getAttribute('data-theme');
    const next = current === 'dark' ? 'light' : 'dark';
    html.setAttribute('data-theme', next);
    if (next === 'light') {
      icon.innerHTML = '<path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>';
    } else {
      icon.innerHTML = '<circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/>';
    }
  });
})();

// =============================================
// Accordion (only one open at a time)
// =============================================
(function() {
  var items = document.querySelectorAll('.accordion-item');
  items.forEach(function(item) {
    var header = item.querySelector('.accordion-header');
    header.addEventListener('click', function() {
      var isActive = item.classList.contains('active');
      items.forEach(function(i) {
        i.classList.remove('active');
        i.querySelector('.accordion-header').setAttribute('aria-expanded', 'false');
      });
      if (!isActive) {
        item.classList.add('active');
        header.setAttribute('aria-expanded', 'true');
      }
    });
  });
})();

// =============================================
// Package Manager Tabs
// =============================================
(function() {
  document.querySelectorAll('.tabs').forEach(function(tabGroup) {
    var accordionItem = tabGroup.closest('.accordion-item');
    var tabBtns = tabGroup.querySelectorAll('.tab-btn');
    var codeContents = accordionItem.querySelectorAll('.tab-content');

    tabBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        var tab = this.getAttribute('data-tab');
        tabBtns.forEach(function(b) {
          b.classList.remove('active');
          b.setAttribute('aria-selected', 'false');
        });
        this.classList.add('active');
        this.setAttribute('aria-selected', 'true');

        codeContents.forEach(function(c) {
          c.classList.remove('active');
          if (c.getAttribute('data-content') === tab) {
            c.classList.add('active');
          }
        });
      });
    });
  });
})();

// =============================================
// Copy to Clipboard
// =============================================
(function() {
  document.querySelectorAll('.copy-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var block = this.parentElement;
      var activeCode = block.querySelector('.tab-content.active') || block.querySelector('code');
      var text = activeCode.textContent.trim();

      navigator.clipboard.writeText(text).then(function() {
        btn.textContent = 'Copied!';
        btn.classList.add('copied');
        setTimeout(function() {
          btn.textContent = 'Copy';
          btn.classList.remove('copied');
        }, 2000);
      }).catch(function() {
        btn.textContent = 'Error';
        setTimeout(function() { btn.textContent = 'Copy'; }, 1500);
